import{c as t,Q as r,j as e,m as n}from"./chunks/framework.BPKcPtvA.js";const h=JSON.parse('{"title":"Tambah & Konfigurasi Router","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/router.md","filePath":"panduan/router.md"}'),o={name:"panduan/router.md"};function i(d,a,s,l,u,g){return r(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="tambah-konfigurasi-router" tabindex="-1">Tambah &amp; Konfigurasi Router <a class="header-anchor" href="#tambah-konfigurasi-router" aria-label="Permalink to &quot;Tambah &amp; Konfigurasi Router&quot;">​</a></h1><p>Router adalah unit utama di eznom. Setiap router MikroTik yang Anda kelola perlu didaftarkan agar pelanggan dan layanan bisa dikelola melalui platform.</p><hr><h2 id="menambah-router-baru" tabindex="-1">Menambah Router Baru <a class="header-anchor" href="#menambah-router-baru" aria-label="Permalink to &quot;Menambah Router Baru&quot;">​</a></h2><ol><li>Dari halaman <strong>Dasbor</strong>, klik tombol <strong>+ Tambah Router</strong></li><li>Ikuti wizard 3 langkah berikut:</li></ol><h3 id="langkah-1-—-informasi-dasar" tabindex="-1">Langkah 1 — Informasi Dasar <a class="header-anchor" href="#langkah-1-—-informasi-dasar" aria-label="Permalink to &quot;Langkah 1 — Informasi Dasar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Nama Router</strong></td><td>Label yang tampil di dasbor, misal: <code>Router Blok A</code></td></tr><tr><td><strong>Deskripsi</strong></td><td>Opsional, misal lokasi atau catatan</td></tr><tr><td><strong>Hostname</strong></td><td>Sufiks username pelanggan, misal: <code>rt-blok-a</code> → username jadi <code>budi@rt-blok-a</code></td></tr></tbody></table><blockquote><p><strong>Aturan hostname:</strong> huruf kecil, angka, tanda hubung (<code>-</code>), dan titik (<code>.</code>). Tidak boleh diawali atau diakhiri tanda hubung/titik.</p></blockquote><h3 id="langkah-2-—-protokol-vpn" tabindex="-1">Langkah 2 — Protokol VPN <a class="header-anchor" href="#langkah-2-—-protokol-vpn" aria-label="Permalink to &quot;Langkah 2 — Protokol VPN&quot;">​</a></h3><p>Pilih protokol VPN yang akan digunakan untuk menghubungkan server eznom ke router MikroTik Anda:</p><ul><li><strong>L2TP/IPsec</strong> — lebih mudah dikonfigurasi, cocok untuk sebagian besar setup</li><li><strong>OpenVPN</strong> — lebih fleksibel, melewati NAT dengan lebih baik</li></ul><p>Setelah memilih protokol, eznom akan menampilkan <strong>konfigurasi yang perlu diterapkan di MikroTik</strong> Anda (IP server, secret/konfigurasi).</p><h3 id="langkah-3-—-pengaturan-tagihan" tabindex="-1">Langkah 3 — Pengaturan Tagihan <a class="header-anchor" href="#langkah-3-—-pengaturan-tagihan" aria-label="Permalink to &quot;Langkah 3 — Pengaturan Tagihan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Tanggal Jatuh Tempo</strong></td><td>Tanggal tiap bulan tagihan jatuh tempo (1–28)</td></tr><tr><td><strong>Prefix ID Pelanggan</strong></td><td>Awalan ID pelanggan, misal <code>C</code> → ID jadi <code>CA3KN7B...</code></td></tr></tbody></table><p>Klik <strong>Simpan &amp; Selesai</strong> untuk menyelesaikan pendaftaran router.</p><hr><h2 id="pengaturan-router" tabindex="-1">Pengaturan Router <a class="header-anchor" href="#pengaturan-router" aria-label="Permalink to &quot;Pengaturan Router&quot;">​</a></h2><p>Setelah router terdaftar, Anda dapat mengubah konfigurasi kapan saja melalui menu <strong>Pengaturan</strong> di sidebar router.</p><h3 id="koneksi-api-mikrotik" tabindex="-1">Koneksi API MikroTik <a class="header-anchor" href="#koneksi-api-mikrotik" aria-label="Permalink to &quot;Koneksi API MikroTik&quot;">​</a></h3><p>eznom perlu terhubung ke API MikroTik untuk sinkronisasi data PPPoE.</p><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Tipe API</strong></td><td><code>Classic API</code> (port 8728) atau <code>REST API</code> (RouterOS 7.1+)</td></tr><tr><td><strong>Host / IP VPN</strong></td><td>IP router di jaringan VPN, misal <code>10.8.0.2</code></td></tr><tr><td><strong>Port</strong></td><td>Default <code>8728</code> untuk Classic, <code>443/80</code> untuk REST</td></tr><tr><td><strong>Username API</strong></td><td>User MikroTik dengan akses API, misal <code>eznom-api</code></td></tr><tr><td><strong>Password API</strong></td><td>Password user API</td></tr></tbody></table><p>Klik <strong>Test Koneksi</strong> untuk memverifikasi sebelum menyimpan.</p><h3 id="remote-modem-pelanggan" tabindex="-1">Remote Modem Pelanggan <a class="header-anchor" href="#remote-modem-pelanggan" aria-label="Permalink to &quot;Remote Modem Pelanggan&quot;">​</a></h3><p>Fitur ini memungkinkan admin mengakses web interface modem pelanggan (webfig) dari dasbor eznom melalui tunnel VPN.</p><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Port VPN Remote Tunnel</strong></td><td>Port yang dibuka di browser admin, misal <code>1639</code></td></tr><tr><td><strong>Dst-Port NAT</strong></td><td>Port NAT di MikroTik: <code>22</code> (SSH) atau <code>80</code> (HTTP/OpenVPN)</td></tr><tr><td><strong>Interface VPN</strong></td><td>Nama interface VPN MikroTik. Kosongkan hanya jika Anda paham risikonya</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Keamanan</p><p>Jika interface VPN dikosongkan, NAT rule berlaku untuk semua interface termasuk jalur publik. Selalu isi nama interface VPN yang spesifik.</p></div><hr><h2 id="dasbor-router" tabindex="-1">Dasbor Router <a class="header-anchor" href="#dasbor-router" aria-label="Permalink to &quot;Dasbor Router&quot;">​</a></h2><p>Dasbor router menampilkan ringkasan kondisi jaringan secara real-time:</p><ul><li><strong>Status pelanggan</strong> — jumlah online, offline, isolir, suspended</li><li><strong>Trafik interface</strong> — grafik upload/download per interface MikroTik</li><li><strong>Peta sebaran</strong> — preview lokasi pelanggan yang sudah memiliki koordinat</li><li><strong>Keuangan ringkas</strong> — total tagihan, lunas, dan tunggakan bulan ini</li></ul><hr><h2 id="status-vpn-router" tabindex="-1">Status VPN Router <a class="header-anchor" href="#status-vpn-router" aria-label="Permalink to &quot;Status VPN Router&quot;">​</a></h2><p>Status koneksi VPN ditampilkan di setiap router:</p><table tabindex="0"><thead><tr><th>Status</th><th>Arti</th></tr></thead><tbody><tr><td>🟢 <strong>Terhubung</strong></td><td>VPN aktif, sinkronisasi real-time tersedia</td></tr><tr><td>🔴 <strong>Terputus</strong></td><td>VPN tidak aktif, sinkronisasi dan isolir otomatis tidak berjalan</td></tr><tr><td>🟡 <strong>Pending</strong></td><td>Router baru didaftarkan, menunggu koneksi pertama</td></tr></tbody></table>',34)])])}const m=t(o,[["render",i]]);export{h as __pageData,m as default};
